function Body($s,$name){Get-AICFMethodBody ([pscustomobject]@{Source=$s;Code=(ConvertTo-AICFCodeText $s)}) $name}
function Convert-Replay($s){
 $s=$s.Replace('protected ','public ').Replace('ref ','').Replace('System.GetTickCount()','Clock.Now')
 $s=$s.Replace('array<AIActionBase> actions = {};','EArray<AIActionBase> actions = new EArray<AIActionBase>();').Replace('bool foundIdle;','bool foundIdle=false;').Replace('AICF_PassiveBoardingRecovery passive;','AICF_PassiveBoardingRecovery passive=null;')
 $s=$s.Replace('foreach (AIActionBase action : actions)','foreach (AIActionBase action in actions)')
 foreach($type in @('SCR_AIUtilityComponent','SCR_AIGroupUtilityComponent')){$s=$s.Replace('FindComponent('+$type+')','FindComponent(typeof('+$type+'))')}
 $s=$s.Replace('m_Idle.Type() != SCR_AIIdleBehavior','m_Idle.Type() != typeof(SCR_AIIdleBehavior)').Replace('m_GroupIdle.Type() != SCR_AIIdleActivity','m_GroupIdle.Type() != typeof(SCR_AIIdleActivity)')
 return $s
}
$scopeReplay=(Convert-Replay $scope).Replace('class AICF_PassiveBoardingRecovery','public class AICF_PassiveBoardingRecovery:N').Replace('static AICF_PassiveBoardingRecovery Capture','public static AICF_PassiveBoardingRecovery Capture').Replace('bool IsCurrent()','public bool IsCurrent()').Replace('bool ConfirmOwnerCancellation()','public bool ConfirmOwnerCancellation()').Replace('bool Matches(','public bool Matches(')
$actual=Convert-Replay (Body $flow 'TryShortPresetSeatRecovery')
$shim=@'
using System;using System.Collections.Generic;
namespace PassiveBoardingReplay {
public class N{public static implicit operator bool(N n){return n!=null;}}
public static class Clock{public static int Now=1000;}
public class EArray<T>:List<T>{public new int Count(){return base.Count;}}
public enum EAIActionState{EVALUATED,RUNNING,FAILED,COMPLETED}
public enum AICF_ETransportTripPhase{BOARDING,TRANSIT,FALLBACK}
public class AIActionBase:N{public EAIActionState State=EAIActionState.RUNNING;public bool Suspended,Remove;public Type Type(){return GetType();}public EAIActionState GetActionState(){return State;}public bool GetActionIsSuspended(){return Suspended;}public bool GetRemoveAction(){return Remove;}}
public class SCR_AIIdleBehavior:AIActionBase{} public class SCR_AIIdleActivity:AIActionBase{} public class ForeignIdle:SCR_AIIdleBehavior{} public class SCR_AIGetInVehicle:AIActionBase{}
public class SCR_AIBaseUtilityComponent:N{public AIActionBase Current,Executed;public EArray<AIActionBase> Actions=new EArray<AIActionBase>();public Action OnRead;public AIActionBase GetCurrentAction(){return Current;}public AIActionBase GetExecutedAction(){return Executed;}public void GetActions(EArray<AIActionBase> a){a.AddRange(Actions);if(OnRead!=null)OnRead();}}
public class SCR_AIUtilityComponent:SCR_AIBaseUtilityComponent{public IEntity m_OwnerEntity;public static SCR_AIUtilityComponent Cast(N n){return n as SCR_AIUtilityComponent;}}
public class SCR_AIGroupUtilityComponent:SCR_AIBaseUtilityComponent{public static SCR_AIGroupUtilityComponent Cast(N n){return n as SCR_AIGroupUtilityComponent;}}
public class IEntity:N{} public class BaseCompartmentSlot:N{}
public class ChimeraCharacter:IEntity{public AIControlComponent Control=new AIControlComponent();public AIControlComponent GetAIControlComponent(){return Control;}public static ChimeraCharacter Cast(IEntity n){return n as ChimeraCharacter;}}
public class AIControlComponent:N{public AIAgent Agent;public AIAgent GetControlAIAgent(){return Agent;}}
public class AIAgent:N{public SCR_AIGroup Group;public ChimeraCharacter Actor;public SCR_AIUtilityComponent Utility;public N FindComponent(Type t){return Utility;}public SCR_AIGroup GetParentGroup(){return Group;}public IEntity GetControlledEntity(){return Actor;}}
public class SCR_AIGroup:N{public SCR_AIGroupUtilityComponent Utility=new SCR_AIGroupUtilityComponent();public N FindComponent(Type t){return Utility;}}
public class AICF_VehicleLease:N{public IEntity Vehicle=new IEntity();public IEntity GetVehicle(){return Vehicle;}}
public class AICF_StrategicAssignmentSnapshot:N{public SCR_AIGroup Group;public SCR_AIGroup GetGroup(){return Group;}}
public class AICF_Stage1Config{public const int MAX_GROUP_SIZE=10;}
public class AICF_VehicleBoardingTokenSet:N{public EArray<AICF_VehicleBoardingActionToken> Items=new EArray<AICF_VehicleBoardingActionToken>();public int Count(){return Items.Count();}public AICF_VehicleBoardingActionToken FindByAgent(AIAgent a){foreach(var t in Items)if(t!=null&&t.Agent==a)return t;return null;}}
public class AICF_VehicleBoardingState:N{public int Deadline=9000;public bool Exited;public AICF_VehicleBoardingTokenSet Tokens=new AICF_VehicleBoardingTokenSet();public int GetAbsoluteDeadlineMs(){return Deadline;}public bool AreExitEffectsApplied(){return Exited;}public AICF_VehicleBoardingTokenSet GetTokens(){return Tokens;}}
public class AICF_TransportTrip:N{public bool Valid=true,Terminal,Preset=true;public AICF_ETransportTripPhase Phase=AICF_ETransportTripPhase.BOARDING;public int Transitions=4;public AICF_VehicleLease Lease=new AICF_VehicleLease();public AICF_StrategicAssignmentSnapshot Assignment=new AICF_StrategicAssignmentSnapshot();public AICF_VehicleBoardingState Board=new AICF_VehicleBoardingState();public bool IsValid(){return Valid;}public bool IsTerminal(){return Terminal;}public bool IsVehiclePresetCurrent(){return Preset;}public bool IsDeadlineReached(int n){return n>=9000;}public AICF_ETransportTripPhase GetPhase(){return Phase;}public int GetTransitionCount(){return Transitions;}public AICF_VehicleLease GetLease(){return Lease;}public AICF_StrategicAssignmentSnapshot GetAssignment(){return Assignment;}public AICF_VehicleBoardingState GetBoardingState(){return Board;}}
public class AICF_VehicleBoardingActionToken:N{public AIAgent Agent;public ChimeraCharacter Actor;public SCR_AIGetInVehicle Entry=new SCR_AIGetInVehicle{State=EAIActionState.EVALUATED};public BaseCompartmentSlot Seat=new BaseCompartmentSlot();public bool Queued=true,Short,Owner=true,Match=true,Owned=true,Current;public int Progress=5000,Age=20000,Cancelled;public Action OnCancel;public AIAgent GetAgent(){return Agent;}public IEntity GetReservedEntity(){return Actor;}public SCR_AIGetInVehicle GetGetInAction(){return Entry;}public BaseCompartmentSlot GetCompartment(){return Seat;}public bool WasPresetQueued(){return Queued;}public bool WasShortRecoveryAttempted(){return Short;}public int GetProgressAgeMs(){return Progress;}public int GetTransitionAgeMs(){return Age;}public bool Matches(AICF_TransportTrip t,AICF_VehicleLease l,SCR_AIGroup g){return Match;}public bool IsPhysicalMutationOwnerSafe(){return Owner;}public bool IsTrackedActionOwnedByUtility(){return Owned;}public bool IsTrackedActionCurrent(){return Current;}public EAIActionState GetActionState(){return Entry.State;}public void CancelOwnerSafe(){Cancelled++;Entry.State=EAIActionState.FAILED;if(OnCancel!=null)OnCancel();}}
public class AICF_AIQuotaVehicleDispatch:N{public static bool Allowed=true;public static Action OnBegin;public bool Current=true;public static AICF_AIQuotaVehicleDispatch Begin(IEntity a,IEntity v,BaseCompartmentSlot s){if(OnBegin!=null)OnBegin();return Allowed?new AICF_AIQuotaVehicleDispatch():null;}public bool IsCurrent(){return Current;}public void Cancel(){Current=false;}}
public class AICF_VehicleShortSeatAttempt:N{public AICF_PassiveBoardingRecovery Proof;public static AICF_VehicleShortSeatAttempt ForBoarding(AICF_TransportTrip t,AICF_VehicleBoardingState s,AICF_VehicleBoardingActionToken tok,AICF_PassiveBoardingRecovery p=null){return new AICF_VehicleShortSeatAttempt{Proof=p};}public bool IsCurrent(AICF_TransportTrip t,IEntity a,BaseCompartmentSlot s,int n){return n<9000;}public bool IsPhysicalDispatchCurrent(){return Proof==null||Proof.IsCurrent();}}
public class AICF_VehicleShortRecovery{public static int Calls;public static bool Safe=true;public static bool CanSeat(AICF_TransportTrip t,IEntity a,BaseCompartmentSlot s){return Safe;}public static bool TrySeat(AICF_TransportTrip t,IEntity a,BaseCompartmentSlot s,string reason,AICF_AIQuotaVehicleDispatch q,AICF_VehicleShortSeatAttempt attempt){if(!attempt.IsPhysicalDispatchCurrent())return false;Calls++;return true;}}
public class Flow{public bool Recover(AICF_TransportTrip trip,AICF_VehicleLease lease,SCR_AIGroup group,AICF_VehicleBoardingState state,AICF_VehicleBoardingActionToken token)FLOWBODY}
'@
$cases=@'
public static class Cases{
static AICF_TransportTrip T;static AICF_VehicleBoardingActionToken Token;static SCR_AIGroup G;static SCR_AIUtilityComponent U;static AIActionBase Idle,GroupIdle;
static void Setup(){Clock.Now=1000;T=new AICF_TransportTrip();G=new SCR_AIGroup();T.Assignment.Group=G;U=new SCR_AIUtilityComponent();var a=new ChimeraCharacter();var agent=new AIAgent{Group=G,Actor=a,Utility=U};a.Control.Agent=agent;U.m_OwnerEntity=a;Token=new AICF_VehicleBoardingActionToken{Actor=a,Agent=agent};T.Board.Tokens.Items.Add(Token);Idle=new SCR_AIIdleBehavior();GroupIdle=new SCR_AIIdleActivity();U.Current=U.Executed=Idle;G.Utility.Current=G.Utility.Executed=GroupIdle;U.Actions.Add(Idle);U.Actions.Add(Token.Entry);G.Utility.Actions.Add(GroupIdle);AICF_AIQuotaVehicleDispatch.Allowed=true;AICF_AIQuotaVehicleDispatch.OnBegin=null;AICF_VehicleShortRecovery.Calls=0;AICF_VehicleShortRecovery.Safe=true;}
static AICF_PassiveBoardingRecovery Capture(){return AICF_PassiveBoardingRecovery.Capture(T,T.Board,Token);}
static bool Dispatch(){return new Flow().Recover(T,T.Lease,G,T.Board,Token);}
public static int Run(){int n=0;Setup();if(!Dispatch()||AICF_VehicleShortRecovery.Calls!=1||Token.Cancelled!=1)throw new Exception("owned evaluated passive proof mustdispatch");n++;
foreach(string kind in new[]{"recent","notQueued","spent","owner","mismatch","selectedForeign","executedForeign","idleSubclass","groupForeign","groupExecuted","suspended","removed","queueForeign","groupQueueForeign","queueNull","overflow","tokenRemoved","phase","phaseABA","terminal","preset","deadline","stateExit","agentControl","actorOwner","wrongGroup","entryRunning"}){Setup();switch(kind){case"recent":Token.Progress=4999;break;case"notQueued":Token.Queued=false;break;case"spent":Token.Short=true;break;case"owner":Token.Owner=false;break;case"mismatch":Token.Match=false;break;case"selectedForeign":U.Current=new AIActionBase();break;case"executedForeign":U.Executed=new AIActionBase();break;case"idleSubclass":U.Current=U.Executed=new ForeignIdle();break;case"groupForeign":G.Utility.Current=new AIActionBase();break;case"groupExecuted":G.Utility.Executed=new AIActionBase();break;case"suspended":Idle.Suspended=true;break;case"removed":GroupIdle.Remove=true;break;case"queueForeign":U.Actions.Add(new AIActionBase{State=EAIActionState.EVALUATED});break;case"groupQueueForeign":G.Utility.Actions.Add(new AIActionBase());break;case"queueNull":U.Actions.Add(null);break;case"overflow":for(int i=0;i<65;i++)U.Actions.Add(new AIActionBase{State=EAIActionState.FAILED});break;case"tokenRemoved":T.Board.Tokens.Items.Clear();break;case"phase":T.Phase=AICF_ETransportTripPhase.TRANSIT;break;case"phaseABA":var p=Capture();T.Transitions+=2;if(p.IsCurrent())throw new Exception(kind);n++;continue;case"terminal":T.Terminal=true;break;case"preset":T.Preset=false;break;case"deadline":Clock.Now=9000;break;case"stateExit":T.Board.Exited=true;break;case"agentControl":Token.Actor.Control.Agent=new AIAgent();break;case"actorOwner":U.m_OwnerEntity=new IEntity();break;case"wrongGroup":Token.Agent.Group=new SCR_AIGroup();break;case"entryRunning":Token.Entry.State=EAIActionState.RUNNING;break;}if(Capture()!=null)throw new Exception(kind);n++;}
foreach(string kind in new[]{"quotaVeto","quotaForeign","quotaPhaseABA","quotaDeadline","cancelForeign","cancelGroupForeign","cancelLease","cancelToken","queueCallback","queueContext"}){Setup();switch(kind){case"quotaVeto":AICF_AIQuotaVehicleDispatch.Allowed=false;break;case"quotaForeign":AICF_AIQuotaVehicleDispatch.OnBegin=()=>U.Executed=new AIActionBase();break;case"quotaPhaseABA":AICF_AIQuotaVehicleDispatch.OnBegin=()=>T.Transitions+=2;break;case"quotaDeadline":AICF_AIQuotaVehicleDispatch.OnBegin=()=>Clock.Now=9000;break;case"cancelForeign":Token.OnCancel=()=>U.Current=new AIActionBase();break;case"cancelGroupForeign":Token.OnCancel=()=>G.Utility.Executed=new AIActionBase();break;case"cancelLease":Token.OnCancel=()=>T.Lease=new AICF_VehicleLease();break;case"cancelToken":Token.OnCancel=()=>T.Board.Tokens.Items.Clear();break;case"queueCallback":U.OnRead=()=>U.Current=new AIActionBase();break;case"queueContext":G.Utility.OnRead=()=>T.Assignment=new AICF_StrategicAssignmentSnapshot();break;}if(Dispatch()||AICF_VehicleShortRecovery.Calls!=0)throw new Exception(kind);n++;}
Setup();var repeated=Capture();if(!repeated.Matches(T,T.Board,Token)||repeated.Matches(new AICF_TransportTrip(),T.Board,Token)||repeated.Matches(T,new AICF_VehicleBoardingState(),Token)||repeated.Matches(T,T.Board,new AICF_VehicleBoardingActionToken()))throw new Exception("cross-context proof");n++;
U.OnRead=()=>U.Current=new AIActionBase();if(repeated.IsCurrent())throw new Exception("last queue callback must invalidate direct proof");n++;
Setup();U.Actions.Add(new AIActionBase{State=EAIActionState.FAILED});G.Utility.Actions.Add(new AIActionBase{State=EAIActionState.COMPLETED});if(!Dispatch())throw new Exception("terminal history is not live competitor");n++;
return n;}}
}
'@
$compiled=$shim.Replace('FLOWBODY',$actual)+$scopeReplay+$cases
Add-Type -TypeDefinition $compiled -Language CSharp
$count=[PassiveBoardingReplay.Cases]::Run()
$oldPath=Join-Path $RepositoryRoot '.codex-runtime/issue78-finalization-20261030/passive-boarding-recovery/before-BoardingFlow.c'
if(Test-Path -LiteralPath $oldPath){$old=Convert-Replay (Body ([IO.File]::ReadAllText($oldPath)) 'TryShortPresetSeatRecovery');$before=($shim.Replace('FLOWBODY',$old)+$scopeReplay+$cases).Replace('PassiveBoardingReplay','PassiveBoardingBefore');Add-Type -TypeDefinition $before; $rejected=$false;try{[void][PassiveBoardingBefore.Cases]::Run()}catch{$rejected=$true};if(!$rejected){throw 'Actual before flow unexpectedly admits observed passive owned EVALUATED case'};'PASS actual_before_flow_rejects_observed_case=1'}
$unsafe=@(@('stall','m_Token.GetProgressAgeMs() < 5000','m_Token.GetProgressAgeMs() < 0'),@('executed','m_Utility.GetExecutedAction() == m_Idle','true'),@('groupExecuted','m_GroupUtility.GetExecutedAction() == m_GroupIdle','true'),@('queue','if (actions.Count() > 64) return false;',''),@('repeat','return ContextCurrent() && PassiveCurrent();','return true;'))
$caught=0
foreach($m in $unsafe){if(!$compiled.Contains($m[1])){throw "Missing mutation $($m[0])"};$ns='PassiveBoardingUnsafe'+$m[0];Add-Type -TypeDefinition ($compiled.Replace('PassiveBoardingReplay',$ns).Replace($m[1],$m[2]));$bad=$false;try{[void]([type]($ns+'.Cases')).GetMethod('Run').Invoke($null,@())}catch{$bad=$true};if(!$bad){throw "Unsafe survived $($m[0])"};$caught++}
$seat=Body $short 'TrySeat'
if($seat.IndexOf('attempt.IsPhysicalDispatchCurrent()')-gt$seat.IndexOf('attempt.Commit(')-or$seat.Substring($seat.IndexOf('attempt.Commit('),$seat.IndexOf('bool accepted = access.GetInVehicle(')-$seat.IndexOf('attempt.Commit('))-match'GetCurrentAction|GetExecutedAction|GetActions|SetReserved|Diagnostics'){throw 'Passive proof crossed pure Commit/native boundary'}
"PASS passive_boarding actual_scope_flow_cases=$count executed_unsafe=$caught unknown_queue_veto=1 native=NOT_RUN"
